/*
 * Site configuration for all Zimmermann regional storefronts.
 * Set SITE_ID env var to control which site is active during a test run.
 * Defaults to 'au' if unset.
 *
 * SITE_CONFIGS comes from site.generated.js (regenerate via
 * `npm run sync:regional-config`, which derives it from live SFCC data) —
 * see site.overlay.js for the hand-maintained fixture-key -> PWA site id
 * mapping that drives generation.
 */

const SITE_CONFIGS = require('./site.generated');

const activeSiteKey = () => process.env.SITE_ID || 'au';
const activeSite = () => SITE_CONFIGS[activeSiteKey()];

module.exports = { SITE_CONFIGS, activeSiteKey, activeSite };

