import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, userEvent, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmNavItem } from '.';

const meta: Meta<typeof ZimmNavItem> = {
  title: 'Elements/ZimmNavItem',
  component: ZimmNavItem,
  argTypes: {
    label: { control: 'text' },
    href: { control: 'text' },
    active: { control: 'boolean' },
    inverse: { control: 'boolean' },
  },
};
export default meta;

type Story = StoryObj<typeof ZimmNavItem>;

const darkDecorator = [
  (Story: React.ComponentType) => (
    <Box bg="background.05" p={4} display="inline-flex">
      <Story />
    </Box>
  ),
];

// ─── Light ───────────────────────────────────────────────────────────────────

export const Default: Story = {
  args: { label: 'New', href: '#' },
};

export const Active: Story = {
  args: { label: 'Clothing', href: '#', active: true },
};

// ─── Inverse (dark background) ───────────────────────────────────────────────

export const Inverse: Story = {
  args: { label: 'New', href: '#', inverse: true },
  decorators: darkDecorator,
};

export const InverseActive: Story = {
  name: 'Inverse — Active',
  args: { label: 'Clothing', href: '#', active: true, inverse: true },
  decorators: darkDecorator,
};

export const PlaceholderButton: Story = {
  name: 'Placeholder — No href (or unsafe href) renders as button',
  render: () => (
    <Box display="flex" flexDirection="column" gap={2} alignItems="flex-start">
      <ZimmNavItem label="Omitted href" />
      <ZimmNavItem label="javascript: href" href="javascript:void(0)" />
      <ZimmNavItem label="data: href" href="data:text/html,xss" />
      <ZimmNavItem label="Protocol-relative href" href="//example.com" />
    </Box>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // SAFE_HREF_RE rejects javascript:, data:, and protocol-relative // hrefs —
    // each must fall back to <button> with no href attribute (not an <a>).
    const cases = ['Omitted href', 'javascript: href', 'data: href', 'Protocol-relative href'];
    for (const label of cases) {
      const el = canvas.getByRole('button', { name: label });
      await expect(el).toBeInTheDocument();
      await expect(el).not.toHaveAttribute('href');
    }
  },
};

// ─── Full nav row (mirrors demo.html) ────────────────────────────────────────

export const NavRowInverse: Story = {
  name: 'Nav Row — Inverse',
  render: () => (
    <Box bg="background.05" p={4} display="flex" gap={8} alignItems="center">
      <ZimmNavItem label="New" href="#" active inverse />
      <ZimmNavItem label="Clothing" href="#" inverse />
      <ZimmNavItem label="Accessories" href="#" inverse />
      <ZimmNavItem label="Collections" href="#" inverse />
      <ZimmNavItem label="Z.Immerse" href="#" inverse />
    </Box>
  ),
};

export const NavRowLight: Story = {
  name: 'Nav Row — Light',
  render: () => (
