import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP `Content` group — the DS's own 218 x 82 frame holding name, price and
 * description. Not an invented grouping.
 *
 * The 20px rhythm is expressed as an adjacent-sibling rule rather than a bottom margin on each
 * child. That is what makes the spacing collapse correctly when an optional field is absent:
 * `ZimmProductDescription` returns `null` when the product has no description, so there is no
 * adjacent sibling and no margin is emitted. A per-child `marginBottom` would need the parent
 * to know which children rendered, and would leave a trailing gap when the last one did not.
 */

/** DS: 20px between the name, price and description rows. Exactly `spacing.l`. */
const SPACE_WITHIN_TEXT_GROUP = 'var(--zimm-scale-l)'; // 20px

export const ZimmProductContent = {
  baseStyle: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'flex-start',

    '& > * + *': {
      marginTop: SPACE_WITHIN_TEXT_GROUP,
    },
  } satisfies SystemStyleObject,
};
